-- case: limits/long-values
CREATE TABLE t(a, b);
INSERT INTO t VALUES(zeroblob(1000000), printf('%.*c', 2000000, 'x'));
SELECT length(a), length(b), substr(b, 1999990), hex(substr(a, 500000, 4)) FROM t;
UPDATE t SET b = b || b;
SELECT length(b) FROM t;
SELECT length(group_concat(b)) FROM (SELECT b FROM t UNION ALL SELECT b FROM t);
-- case: limits/many-rows-order-group
CREATE TABLE t(k, v);
WITH RECURSIVE c(x) AS (SELECT 1 UNION ALL SELECT x+1 FROM c WHERE x<20000) INSERT INTO t SELECT x % 97, x FROM c;
SELECT k, count(*), sum(v), min(v), max(v) FROM t GROUP BY k ORDER BY sum(v) DESC LIMIT 5;
SELECT count(DISTINCT v % 1000) FROM t;
SELECT v FROM t ORDER BY v % 13, v DESC LIMIT 3 OFFSET 100;
CREATE INDEX tk ON t(k, v);
SELECT k, max(v) FROM t WHERE k BETWEEN 10 AND 12 GROUP BY k;
