-- case: limits/negative-limit-with-offset-every-shape
CREATE TABLE t(a INTEGER PRIMARY KEY, b); INSERT INTO t VALUES(1,5),(2,4),(3,3),(4,2),(5,1);
SELECT a FROM t ORDER BY a LIMIT -1 OFFSET 3;
SELECT a FROM t LIMIT -1 OFFSET 3;
SELECT a FROM t ORDER BY b LIMIT -1 OFFSET 3;
SELECT a FROM t ORDER BY b LIMIT -5 OFFSET 2;
SELECT a FROM t LIMIT 3 OFFSET 4;
SELECT a FROM t LIMIT 0 OFFSET 1;
SELECT a FROM t LIMIT 2, 2;
SELECT a FROM t LIMIT -1, 2;
SELECT a FROM t LIMIT -1 OFFSET -2;
SELECT a FROM t LIMIT 2 OFFSET -2;
