CREATE VIEW v AS SELECT a FROM t;
SELECT a FROM v LIMIT -1 OFFSET 2;
SELECT a FROM v ORDER BY a DESC LIMIT -1 OFFSET 2;
CREATE VIEW vl AS SELECT a FROM t ORDER BY a LIMIT -1 OFFSET 1;
SELECT a FROM vl;
SELECT a FROM vl LIMIT 2 OFFSET 1;
SELECT DISTINCT b > 2 FROM t LIMIT -1 OFFSET 1;
SELECT count(*) FROM t GROUP BY b > 2 ORDER BY 1 LIMIT -1 OFFSET 1;
SELECT a FROM t WHERE a > 1 LIMIT -1 OFFSET 1;
SELECT a, row_number() OVER (ORDER BY a) FROM t LIMIT -1 OFFSET 3;
