SELECT a FROM t LIMIT -1.0 OFFSET 3.0;
WITH c(x) AS (SELECT a FROM t) SELECT x FROM c LIMIT -1 OFFSET 3;
WITH RECURSIVE c(x) AS (SELECT 1 UNION ALL SELECT x+1 FROM c WHERE x < 6) SELECT x FROM c LIMIT -1 OFFSET 4;
SELECT a, x FROM t, (SELECT 1 AS x UNION ALL SELECT 2) ORDER BY a, x LIMIT -1 OFFSET 8;
SELECT a FROM t WHERE a IN (SELECT a FROM t LIMIT -1 OFFSET 3);
SELECT (SELECT a FROM t ORDER BY a LIMIT -1 OFFSET 2);
SELECT a FROM t WHERE a = 2 OR a = 4 LIMIT -1 OFFSET 1;
SELECT a FROM t WHERE a IN (1,3,5) ORDER BY a LIMIT -1 OFFSET 1;
